		public static global::System.Collections.IEnumerator CreateNPC(global::UnityEngine.Vector2Int grid, string assetPath, global::System.Action<global::FieldObjectEntity> OnLoad, int id = 0) {
            string name = GetAssetNamebyPath(assetPath);
            yield return LoadAsset(assetPath, asset =>
            {
                if (asset.name == name)
                {
                    GameObject go = UnityEngine.Object.Instantiate(asset) as GameObject;
                    go.name = name;
                    FieldObjectEntity entity = go.transform.GetComponent<FieldObjectEntity>();
                    entity.gridPositionDirect = grid;
                    OnLoad?.Invoke(entity);
                    EntityManager.Add(entity);
                    EntityManager.BuildFieldEntities();
                }
            }, false, true, id);
        }
		public static void BGM_FadeOut(float duration, global::System.Action OnComplete = null) {
            float volume = AudioManager.Instance.GetVolume(AudioManager.ListenerType.Bgm, AudioManager.VolumeType.Normal);
            DG.Tweening.TweenSettingsExtensions.OnComplete(
                DG.Tweening.DOTween.To(() => volume, x => AudioManager.Instance.SetVolume(AudioManager.ListenerType.Bgm, x, AudioManager.VolumeType.Normal), 0f, duration),
                () =>
                {
                    AudioManager.Instance.SetVolume(AudioManager.ListenerType.Bgm, volume, AudioManager.VolumeType.Normal);
                    OnComplete?.Invoke();
                });
        }
