		public static string CheckNGTrainerName(ref string trainerName, global::Dpr.Message.MessageEnumData.MsgLangId langId, int cassetVersion) {
            int maxLength = SoftwareKeyboard.LanguageMaxLength(GetPersonNameLength(), langId);
            if (string.IsNullOrEmpty(trainerName) || trainerName.Length > maxLength ||
                SoftwareKeyboard.CheckNgWords(ref trainerName, 0, langId) != SoftwareKeyboard.ErrorState.None)
                return GetReplacedNGName(cassetVersion);

            return trainerName;
        }
		private static int GetPersonNameLength() {
            return 6;
        }
		public static string CheckNGPokeName(ref string nickname, global::Pml.MonsNo monsNo, global::Dpr.Message.MessageEnumData.MsgLangId langId) {
            int maxLength = SoftwareKeyboard.LanguageMaxLength(GetMonsNameLength(), langId);
            if (string.IsNullOrEmpty(nickname) || nickname.Length > maxLength ||
                SoftwareKeyboard.CheckNgWords(ref nickname, 0, langId) != SoftwareKeyboard.ErrorState.None)
                return Pml.Personal.PersonalSystem.GetMonsName(monsNo, langId);

            return nickname;
        }
		public static string CheckNGPokeName(global::Pml.PokePara.PokemonParam param) {
            string nickname = param.GetNickName();
            var langId = (MessageEnumData.MsgLangId)param.GetLangId();
            int maxLength = SoftwareKeyboard.LanguageMaxLength(GetMonsNameLength(), langId);
            if (string.IsNullOrEmpty(nickname) || nickname.Length > maxLength ||
                SoftwareKeyboard.CheckNgWords(ref nickname, 0, langId) != SoftwareKeyboard.ErrorState.None)
            {
                param.SetDefaultNickName();
                return param.GetNickName();
            }

            return nickname;
        }
		private static int GetMonsNameLength() {
            return 6;
        }
		public static string CheckNGGroupName(ref string groupName, global::Dpr.Message.MessageEnumData.MsgLangId langId, int cassetVersion) {
            int maxLength = SoftwareKeyboard.LanguageMaxLength(GROUP_NAME_LNGTH, langId);
            if (string.IsNullOrEmpty(groupName) || groupName.Length > maxLength ||
                SoftwareKeyboard.CheckNgWords(ref groupName, 0, langId) != SoftwareKeyboard.ErrorState.None)
                return GetReplacedNGName(cassetVersion);

            return groupName;
        }
		private static string GetReplacedNGName(int cassetVersion) {
            var msgFile = MessageManager.Instance.GetMsgFile("dp_characters");
            var sb = new System.Text.StringBuilder();
            sb.Append(msgFile.GetNameStr(cassetVersion == CassetVersion.DPR_S ? "DP_CHARACTERS_247" : "DP_CHARACTERS_206"));
            sb.Append(MessageHelper.ConvertUnicodeToChar(0x2e));
            return sb.ToString();
        }
		public static void OpenPasswordSoftwareKeyboard(global::System.Action<bool, string> result) {
            var param = new SoftwareKeyboard.Param
            {
                keyboardMode = SoftwareKeyboard.KeyboardMode.Numeric,
                passwordMode = SoftwareKeyboard.PasswordMode.Show,
                text = string.Empty,
                textMaxLength = 8,
                textMinLength = 8,
                headerText = SoftwareKeyboard.GetMessageText("SS_strinput_026"),
                subText = null,
                guideText = null,
                okText = null,
            };

            SoftwareKeyboard.Open(param,
                (text, errorState) => (errorState == SoftwareKeyboard.ErrorState.None && text.Length > 7, string.Empty),
                (isSuccess, text) => result?.Invoke(isSuccess, text));
        }
		public static int GetPokeRarityNum(global::Pml.MonsNo monsNo) {
            for (int i = 0; i < very_rare_monsno.Length; i++)
            {
                if (very_rare_monsno[i] == monsNo)
                    return POKE_RARITY_VERY_RARE;
            }
            for (int i = 0; i < legend_rare_monsno.Length; i++)
            {
                if (legend_rare_monsno[i] == monsNo)
                    return POKE_RARITY_LEGEND_RARE;
            }
            for (int i = 0; i < sub_legend_rare_monsno.Length; i++)
            {
                if (sub_legend_rare_monsno[i] == monsNo)
                    return POKE_RARITY_SUB_LEGEND_RARE;
            }
            return 0;
        }
		public static bool CheckInvalidTradePoke(global::Pml.MonsNo monsNo) {
            // Shipped: false when the species IS in very_rare_monsno, true otherwise (@0186f8a4 / @0186f8b8).
            for (int i = 0; i < very_rare_monsno.Length; i++)
            {
                if (very_rare_monsno[i] == monsNo)
                    return false;
            }
            return true;
        }
