		public static global::Pml.PokePara.PokemonParam UpdateTranerMemo(global::Pml.PokePara.PokemonParam updateParam) {
            updateParam.UpdateOwnerInfo(new OwnerInfo(PlayerWork.playerStatus));
            if (!updateParam.IsEgg(EggCheckType.BOTH_EGG))
                poketool.poke_memo.poketool_poke_memo.ClearPlaceTime(updateParam, poketool.poke_memo.DataType.DATA_TYPE_EGG_TAKEN);
            poketool.poke_memo.poketool_poke_memo.SetPlaceTime(updateParam, 30001, poketool.poke_memo.DataType.DATA_TYPE_FIRST_CONTACT);
            poketool.poke_memo.poketool_poke_memo.SetGetLevel(updateParam);
            return updateParam;
        }
